const items = $input.all();
const rows = items.map(item => item.json.row || []);

const file = $('On form submission').first()
  .binary?.document_file;

const filename = file?.fileName || 'unknown.xlsx';

const documentId = filename
  .replace(/\.[^.]+$/, '')
  .replace(/[^a-zA-Z0-9_-]/g, '-')
  .toLowerCase();

const isFilled = value =>
  value !== null &&
  value !== undefined &&
  String(value).trim() !== '';

const clean = value => String(value ?? '').trim();

if (rows.length === 0) return [];

// Detect likely header row
let headerIndex = -1;
let bestScore = -1;

for (let i = 0; i < Math.min(rows.length, 15); i++) {
  const cells = rows[i];
  const filled = cells.filter(isFilled);

  const textCells = filled.filter(v =>
    typeof v === 'string' &&
    !/^https?:\/\//i.test(v)
  );

  const score = filled.length >= 2
    ? textCells.length * 2 + filled.length
    : -1;

  if (score > bestScore) {
    bestScore = score;
    headerIndex = i;
  }
}

if (headerIndex < 0) {
  throw new Error('Could not detect an Excel header row');
}

const headers = rows[headerIndex].map(
  (value, index) =>
    isFilled(value)
      ? clean(value)
      : `Column_${index + 1}`
);

const output = [];

for (let i = headerIndex + 1; i < rows.length; i++) {
  const cells = rows[i];

  const fields = headers
    .map((header, index) => ({
      header,
      value: cells[index]
    }))
    .filter(field => isFilled(field.value));

  if (fields.length === 0) continue;

  const text = fields
    .map(field =>
      `${field.header}: ${clean(field.value)}`
    )
    .join('\n');

  output.push({
    json: {
      id: `${documentId}-row-${i + 1}`,
      text,
      source: filename,
      file_type: 'xlsx',
      document_id: documentId,
      chunk_index: i + 1,
      row_number: i + 1,
      detected_header_row: headerIndex + 1,
      fields: Object.fromEntries(
        fields.map(field => [
          field.header,
          field.value
        ])
      )
    }
  });
}

return output;

const items = $input.all();
const results = [];

const chunkSize = 1000;
const overlap = 200;
const step = chunkSize - overlap;

const file = $('On form submission')
  .first().binary?.document_file;

const filename = file?.fileName || 'unknown.pdf';

const documentId = filename
  .replace(/\.pdf$/i, '')
  .replace(/[^a-zA-Z0-9_-]/g, '-')
  .toLowerCase();

for (const item of items) {
  const text = item.json.text || '';

  if (!text.trim()) continue;

  let chunkIndex = 0;

  for (let start = 0; start < text.length; start += step) {
    const chunk = text.slice(start, start + chunkSize);

    if (!chunk.trim()) continue;

    results.push({
      json: {
        id: `${documentId}-chunk-${chunkIndex}`,
        text: chunk,
        source: filename,
        file_type: 'pdf',
        document_id: documentId,
        chunk_index: chunkIndex
      }
    });

    chunkIndex++;

    if (start + chunkSize >= text.length) break;
  }
}

return results;

