const responses = $input.all();

// Identify which file type was uploaded
const file = $('On form submission')
  .first().binary.document_file;

const extension = file.fileExtension.toLowerCase();

// Select the active normalization node
const originals = extension === 'pdf'
  ? $('Code in JavaScript1').all()
  : $('Code in JavaScript').all();

if (originals.length !== responses.length) {
  throw new Error(
    `Count mismatch: ${originals.length} originals, ` +
    `${responses.length} embeddings`
  );
}

return responses.map((item, index) => {
  const original = originals[index].json;
  const vector = item.json.data?.[0]?.embedding;

  if (!original.id || !original.text) {
    throw new Error(
      `Missing original metadata at item ${index}`
    );
  }

  if (!Array.isArray(vector) || vector.length !== 4096) {
    throw new Error(
      `Invalid embedding at item ${index}`
    );
  }

  return {
    json: {
      id: original.id,
      values: vector,
      metadata: {
        text: original.text,
        source: original.source,
        file_type: original.file_type,
        document_id: original.document_id,
        chunk_index: original.chunk_index
      }
    }
  };
});
